import path from 'path';
import fs from 'fs';
import sharp from 'sharp';
import { log } from './logger.js';
const DENSITIES = [
    { name: 'mipmap-mdpi', multiplier: 1 }, // 48px / 108px
    { name: 'mipmap-hdpi', multiplier: 1.5 }, // 72px / 162px
    { name: 'mipmap-xhdpi', multiplier: 2 }, // 96px / 216px
    { name: 'mipmap-xxhdpi', multiplier: 3 }, // 144px / 324px
    { name: 'mipmap-xxxhdpi', multiplier: 4 }, // 192px / 432px
];
const LEGACY_DP = 48;
const ADAPTIVE_DP = 108;
export async function generateIcons(config, resDir) {
    if (!config.icon) {
        log.warn('No icon set - using blue placeholder. Set `icon` in webapkify.config.ts.');
        await generatePlaceholderIcons(config, resDir);
        return;
    }
    const iconSource = path.resolve(process.cwd(), config.icon);
    if (!fs.existsSync(iconSource)) {
        log.warn(`Icon not found at ${iconSource} - using placeholder.`);
        await generatePlaceholderIcons(config, resDir);
        return;
    }
    log.step('Generating launcher icons...');
    const foregroundSource = config.adaptiveIconForeground ? path.resolve(process.cwd(), config.adaptiveIconForeground) : iconSource;
    for (const density of DENSITIES) {
        const directory = path.join(resDir, density.name);
        fs.mkdirSync(directory, { recursive: true });
        const legacyPx = Math.round(LEGACY_DP * density.multiplier);
        const adaptivePx = Math.round(ADAPTIVE_DP * density.multiplier);
        await sharp(iconSource).resize(legacyPx, legacyPx, { fit: 'cover' }).png().toFile(path.join(directory, 'ic_launcher.png'));
        await sharp(foregroundSource).resize(adaptivePx, adaptivePx, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toFile(path.join(directory, 'ic_launcher_foreground.png'));
        const background = hexToRgb(config.adaptiveIconBackground ?? '#FFFFFF');
        await sharp({ create: { width: adaptivePx, height: adaptivePx, channels: 4, background: { ...background, alpha: 255 } } }).png().toFile(path.join(directory, 'ic_launcher_background.png'));
        log.dim(`  ${density.name}: ${legacyPx}px legacy, ${adaptivePx}px adaptive layers`);
    }
    const drawableDirectory = path.join(resDir, 'drawable');
    fs.mkdirSync(drawableDirectory, { recursive: true });
    await sharp(foregroundSource).resize(432, 432, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toFile(path.join(drawableDirectory, 'ic_launcher_foreground.png'));
    const monoSource = config.monochromeIcon ? path.resolve(process.cwd(), config.monochromeIcon) : foregroundSource;
    if (monoSource.endsWith('.svg') || monoSource.endsWith('.xml')) {
        fs.copyFileSync(monoSource, path.join(drawableDirectory, 'ic_launcher_monochrome.xml'));
        log.dim('  Monochrome: copied vector drawable');
    }
    else {
        await sharp(monoSource).resize(432, 432, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).grayscale().png().toFile(path.join(drawableDirectory, 'ic_launcher_monochrome.png'));
        log.dim('  Monochrome: generated grayscale PNG for themed icons');
    }
    const anydpiDirectory = path.join(resDir, 'mipmap-anydpi-v26');
    fs.mkdirSync(anydpiDirectory, { recursive: true });
    writeAdaptiveIconXml(anydpiDirectory, 'ic_launcher.xml');
    writeAdaptiveIconXml(anydpiDirectory, 'ic_launcher_round.xml');
    log.dim('  mipmap-anydpi-v26 adaptive XMLs written');
    const valuesDirectory = path.join(resDir, 'values');
    fs.mkdirSync(valuesDirectory, { recursive: true });
    writeBackgroundColorRes(valuesDirectory, config.adaptiveIconBackground ?? '#FFFFFF');
    log.success('Icons generated');
}
function writeAdaptiveIconXml(dir, filename) {
    const xml = `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background" />
    <foreground android:drawable="@drawable/ic_launcher_foreground" />
    <monochrome android:drawable="@drawable/ic_launcher_monochrome" />
</adaptive-icon>`;
    fs.writeFileSync(path.join(dir, filename), xml);
}
function writeBackgroundColorRes(valuesDir, hex) {
    const xml = `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="ic_launcher_background">${hex}</color>
</resources>`;
    fs.writeFileSync(path.join(valuesDir, 'ic_launcher_background.xml'), xml);
}
async function generatePlaceholderIcons(config, resDir) {
    for (const density of DENSITIES) {
        const directory = path.join(resDir, density.name);
        const legacyPx = Math.round(LEGACY_DP * density.multiplier);
        const adaptivePx = Math.round(ADAPTIVE_DP * density.multiplier);
        fs.mkdirSync(directory, { recursive: true });
        const blue = { r: 33, g: 150, b: 243, alpha: 255 };
        await sharp({ create: { width: legacyPx, height: legacyPx, channels: 3, background: { r: 33, g: 150, b: 243 } } }).png().toFile(path.join(directory, 'ic_launcher.png'));
        await sharp({ create: { width: adaptivePx, height: adaptivePx, channels: 4, background: blue } }).png().toFile(path.join(directory, 'ic_launcher_foreground.png'));
        await sharp({ create: { width: adaptivePx, height: adaptivePx, channels: 4, background: { r: 255, g: 255, b: 255, alpha: 255 } } }).png().toFile(path.join(directory, 'ic_launcher_background.png'));
    }
    const drawableDirectory = path.join(resDir, 'drawable');
    const anydpiDirectory = path.join(resDir, 'mipmap-anydpi-v26');
    const valuesDirectory = path.join(resDir, 'values');
    fs.mkdirSync(drawableDirectory, { recursive: true });
    fs.mkdirSync(anydpiDirectory, { recursive: true });
    fs.mkdirSync(valuesDirectory, { recursive: true });
    const blue432 = { r: 33, g: 150, b: 243, alpha: 255 };
    await sharp({ create: { width: 432, height: 432, channels: 4, background: blue432 } }).png().toFile(path.join(drawableDirectory, 'ic_launcher_foreground.png'));
    await sharp({ create: { width: 432, height: 432, channels: 4, background: blue432 } }).grayscale().png().toFile(path.join(drawableDirectory, 'ic_launcher_monochrome.png'));
    writeAdaptiveIconXml(anydpiDirectory, 'ic_launcher.xml');
    writeAdaptiveIconXml(anydpiDirectory, 'ic_launcher_round.xml');
    writeBackgroundColorRes(valuesDirectory, config.adaptiveIconBackground ?? '#FFFFFF');
}
function hexToRgb(hex) {
    const h = hex.replace('#', '');
    return { r: parseInt(h.slice(0, 2), 16), g: parseInt(h.slice(2, 4), 16), b: parseInt(h.slice(4, 6), 16) };
}
